# Compute candidate diagonal fills (center if diagonal endpoints two steps apart in both row/col)
for r in range(R):
 for c in range(C):
  if grid[r][c]==7 and any(0<=r+2*dr<R and 0<=c+2*dc<C and grid[r+2*dr][c+2*dc]==6 and grid[r][c]==7 and grid[r+dr][c+dc]==7 and grid[r][c]==7 and grid[r-2*dr][c-2*dc]==6 for dr,dc in []): pass
# simple count midpoint coords for same 6 endpoints delta (2,2), (2,-2)
diag=set()
for r in range(R):
 for c in range(C):
  if grid[r][c]==6:
   for dr,dc in [(2,2),(2,-2)]:
    rr,cc=r+dr,c+dc
    if 0<=rr<R and 0<=cc<C and grid[rr][cc]==6 and grid[r+1][c+dc//2]==7:
     diag.add((r+1,c+dc//2))
print(sorted(diag))

