   a=(r-dr,c-dc); b=(r+dr,c+dc)
   if 0<=a[0]<R and 0<=b[0]<R and 0<=a[1]<C and 0<=b[1]<C and grid[a[0]][a[1]]==grid[b[0]][b[1]]==6 and grid[r][c]==7:
    fills.add((r,c));out8[r][c]=2
print('fills',sorted(fills));print('\n'.join(str(x) for x in out8))

